-- Autogenerated thumbnail metadata for published completed-project videos.
-- The underlying original and playback derivative remain private in Cloudflare R2.
ALTER TABLE business_profile_projects
  ADD COLUMN IF NOT EXISTS video_thumbnail_url TEXT,
  ADD COLUMN IF NOT EXISTS video_thumbnail_source_url TEXT,
  ADD COLUMN IF NOT EXISTS video_thumbnail_generated_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS video_duration_seconds NUMERIC(10,2);

COMMENT ON COLUMN business_profile_projects.video_thumbnail_url IS
  'Private R2 JPEG derivative; only exposed via the public-eligibility-gated thumbnail endpoint.';
COMMENT ON COLUMN business_profile_projects.video_thumbnail_source_url IS
  'Exact original upload reference that thumbnail was generated from, for safe source matching.';
COMMENT ON COLUMN business_profile_projects.video_duration_seconds IS
  'Measured playback derivative duration in seconds, not a manually estimated duration.';
